-- Collection-Bound promo fixes (Nov 10 2026). Run AFTER the GitHub PR is merged.
-- Safe to run more than once.

-- 1. Worlds 2025: the second Playmat / Deckbox / Sleeves set is the ENGLISH bundle
--    (Riot Merch Store), not a second Chinese copy. The English playmat shows
--    "Image coming soon" until an English picture is found (the old one has Chinese text).
update promo_items set data = data || '{"la":"English"}'::jsonb
 where id in ('item-304','item-305','item-306');
update promo_items set data = jsonb_set(data, '{img}', '""'::jsonb) where id = 'item-304';

-- 2. Altar to Unity [Autel d'unité]: one promo, given out at two events.
--    item-63 keeps both events; item-354 is removed (the tracker moves anyone
--    who marked item-354 over to item-63 automatically).
update promo_items set data = data || jsonb_build_object(
  'nm', 'Altar to Unity [Autel d’unité]',
  'ev', E'TFT - Paris, France\nLRT - France',
  'evl', E'Teamfight Tactics Paris Open: first ever French promo\nLe Rift Tour Phase 2: Division Qualifier (September 2026), participation prize at select local game stores',
  'tg', E'Battlefield\nParis Open\nLe Rift Tour',
  'inf', E'Same promo given out at two French events: the Teamfight Tactics Paris Open (first ever French promo) and Le Rift Tour Phase 2: Division Qualifier (September), as the participation prize.\n\nLe Rift Tour Phase 2 prizing: Division Winner 1 Gold Le Rift Tour Coin, Division Finalist 1 Silver Le Rift Tour Coin, Division Top 8 1 Bronze Le Rift Tour Coin. Top 8: hotel and transportation to the Final Stage and French Riftbound Booster Packs.')
 where id = 'item-63';
delete from promo_items where id = 'item-354';

-- 3. Jayce - Man of Progress: the card is printed in ENGLISH (SFD 084), the same
--    promo handed out at Evo 2026 and other conventions.
update promo_items set data = data || jsonb_build_object(
  'nm', 'Jayce - Man of Progress (Promo)',
  'la', 'English',
  'cn', '084',
  'ev', E'LRT - France\nMultiple Events/Cons global regions excluding China',
  'evl', E'Le Rift Tour Phase 1: Store Qualifier (July - August 2026), participation prize\nEvo 2026: on-site missions at the Riftbound booth\nOther special events and conventions in 2026',
  'tg', E'Champion Unit\nJayce\nPiltover',
  'inf', E'English-language promo. Participation prize for Le Rift Tour Phase 1: Store Qualifier (July - August), also handed out at Evo 2026 and other conventions.\n\nLe Rift Tour: 3 competitive phases (Store Qualifiers, Division Qualifiers, Final Stage). Finalists earn qualification to the Europe Regional Championship.')
 where id = 'item-10260';

-- 4. 1/300 cardback sheet: members pick their number (1-300) and can upload a
--    photo of the certificate that came with it.
update promo_items set data = data || jsonb_build_object(
  'sx', 300,
  'sc', 'Cardback sheet',
  'sn', 'Each sheet is numbered out of 300 and came with a certificate of authenticity. Add the number on yours and upload a photo of your certificate.')
 where id = 'item-265';

-- 5. Unleashed Nexus Night Blossom runes (English) had the Chinese pictures.
with pics(id, img) as (values
  ('item-10152', 'https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/calm-rune-blossom-item-10026.webp'),
  ('item-10153', 'https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/fury-rune-blossom-item-10028.webp'),
  ('item-10154', 'https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/mind-rune-blossom-item-10025.webp'),
  ('item-10155', 'https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/body-rune-blossom-item-10029.webp'),
  ('item-10156', 'https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/chaos-rune-blossom-item-10024.webp'),
  ('item-10157', 'https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/order-rune-blossom-item-10027.webp')
)
update promo_items p set data = jsonb_set(p.data, '{img}', to_jsonb(pics.img))
from pics where p.id = pics.id;

select id, data->>'nm' as name, data->>'la' as language, data->>'ev' as event
from promo_items where id in ('item-63','item-265','item-304','item-305','item-306','item-10260','item-10152')
order by r;

